W 'const MO=["Jan","Feb","Mar","Apr","Mei","Jun","Jul","Agu","Sep","Okt","Nov","Des"];'
W 'const MM={JAN:0,JANUARI:0,FEB:1,FEBRUARI:1,MAR:2,MARET:2,APR:3,APRIL:3,MEI:4,MAY:4,JUN:5,JUNI:5,JUL:6,JULI:6,AGU:7,AGUSTUS:7,AUG:7,SEP:8,SEPTEMBER:8,OKT:9,OKTOBER:9,OCT:9,NOV:10,NOVEMBER:10,DES:11,DESEMBER:11,DEC:11};'
W 'function fI(n){return"Rp "+Math.round(Number(n||0)).toLocaleString("id-ID")}'
W 'function pM(v){if(!v)return 0;let s=String(v).replace(/[^\d,.-]/g,"");if(!s)return 0;const hc=s.includes(","),hd=s.includes(".");if(hc&&hd){const lc=s.lastIndexOf(","),ld=s.lastIndexOf(".");s=ld>lc?s.replace(/,/g,""):s.replace(/\./g,"").replace(",",".")}else if(hc){const p=s.split(",");s=p[p.length-1].length===2?p.slice(0,-1).join("")+"."+p[p.length-1]:s.replace(/,/g,"")}else if(hd){const p=s.split(".");if(p.length>2||p[p.length-1].length===3)s=s.replace(/\./g,"")}return Number(s)||0}'
W 'function b64U8(b){const bs=atob(b);const u=new Uint8Array(bs.length);for(let i=0;i<bs.length;i++)u[i]=bs.charCodeAt(i);return u}'
W 'function es(s){return String(s||"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]))}'
W 'function apTm(t){theme=t;document.documentElement.setAttribute("data-theme",t);localStorage.setItem("ATM",t);const d=t==="dark";document.getElementById("tmEm").textContent=d?"☀️":"🌙";document.getElementById("tmLb").textContent=d?"Mode Terang":"Mode Gelap";document.getElementById("tpTmEm").textContent=d?"☀️":"🌙"}'
