W 'const TM={ov:{t:"Selamat datang, Fahmi Fahrezy.",s:"Audit Finansial Terpadu 2023-2026"},bca:{t:"Mutasi BCA",s:"41 Bulan - 1.801 Transaksi"},jd:{t:"Judi Online 1xBet",s:"628 Deposit - Net Loss -Rp 4.760.602"},pj:{t:"Pinjol Shopee",s:"SPinjam & SPayLater - Total ~Rp 4.766.903"},kl:{t:"Biaya Kuliah",s:"7 Semester - Total Rp 38.800.000"},an:{t:"Rekonsiliasi Silang",s:"Komparasi BCA vs 1xBet vs Pinjol"},lb:{t:"Buku Besar Gabungan",s:"Seluruh transaksi dari semua sumber"}};'
W 'function sw(tab){actTab=tab;document.querySelectorAll(".panel").forEach(p=>p.classList.remove("act"));document.querySelectorAll(".nb").forEach(b=>b.classList.remove("act"));const p=document.getElementById("p-"+tab);if(p)p.classList.add("act");const idx=["ov","bca","jd","pj","kl","an","lb"].indexOf(tab);const bs=document.querySelectorAll(".nb");if(bs[idx])bs[idx].classList.add("act");const m=TM[tab]||{};document.getElementById("tpTl").textContent=m.t||tab;document.getElementById("tpSb").textContent=m.s||"";if(tab==="bca")rBca();if(tab==="jd")rXbt();if(tab==="lb")rLed()}'

# PDF parsing
W 'async function pdfBytes(bytes,fn){'
W '  const pdf=await pdfjsLib.getDocument({data:bytes,disableWorker:true,useWorkerFetch:false,isEvalSupported:false}).promise;'
W '  const pages=[];'
W '  for(let pn=1;pn<=pdf.numPages;pn++){'
W '    const pg=await pdf.getPage(pn);const c=await pg.getTextContent();'
W '    const it=c.items.map(i=>({t:i.str,x:Math.round(i.transform[4]),y:Math.round(i.transform[5])})).filter(i=>i.t.trim());'
W '    it.sort((a,b)=>Math.abs(b.y-a.y)>3?b.y-a.y:a.x-b.x);'
W '    const ln=[];for(const i of it){const L=ln[ln.length-1];if(!L||Math.abs(L.y-i.y)>3)ln.push({y:i.y,p:[i]});else L.p.push(i)}'
W '    pages.push(ln.map(l=>{l.p.sort((a,b)=>a.x-b.x);return l.p.map(p=>p.t).join(" ").replace(/\s+/g," ").trim();}).join("\n"));'
W '  }'
W '  return parseSt(pages.join("\n"),fn);'
W '}'
W 'function parseSt(text,fn){'
W '  const meta=getMeta(text,fn);'
W '  const lines=text.split(/\r?\n/).map(l=>l.trim()).filter(Boolean);'
W '  const txs=[];let cur=null,ad=null;'
W '  for(const raw of lines){'
W '    const line=raw.replace(/\s+/g," ").trim();'
W '    const dm=line.match(/^(\d{2})\/(\d{2})(?:\s+(.+))?$/);'
W '    if(dm){if(cur)txs.push(finTx(cur,meta));ad={day:Number(dm[1]),month:Number(dm[2])-1,year:meta.year};cur={...ad,lines:[dm[3]||""],file:fn};continue}'
W '    if(!cur)continue;'
W '    if(/^(REKENING|KCU|CATATAN|TANGGAL|Bersambung|HALAMAN|MATA UANG)/i.test(line))continue;'
W '    if(/^(MUTASI CR|MUTASI DB|SALDO AKHIR|SALDO AWAL\s*:)/i.test(line))continue;'
W '    cur.lines.push(line);'
W '  }'
W '  if(cur)txs.push(finTx(cur,meta));'
W '  return{txs:txs.filter(Boolean),summary:meta.summary,meta};'
W '}'
W 'function getMeta(text,fn){'
W '  const acct=(text.match(/NO\.?\s*REKENING\s*:?\s*(\d+)/i)||[])[1]||"1210931399";'
W '  const pr=(text.match(/PERIODE\s*:?\s*([A-Z]+)\s+(\d{4})/i)||[]);'
W '  const mn=pr[1]||(Object.keys(MM).find(n=>fn.toUpperCase().includes(n))||"");'
W '  const ym=fn.match(/20\d{2}/);const year=Number(pr[2]||(ym?ym[0]:2024));'
W '  const month=MM[mn.toUpperCase()]??0;'
W '  const pl=mn?`${MO[month]||mn} ${year}`:String(year);'
W '  const mk=`${year}-${String(month+1).padStart(2,"0")}`;'
W '  const nums=exNums(text);'
W '  const summary={file:fn,monthKey:mk,periodLabel:pl,totalIn:pM(nums?.cr||0),totalOut:pM(nums?.db||0),openingBalance:pM(nums?.op||0),endingBalance:pM(nums?.en||0)};'
W '  return{acct,year,month,periodLabel:pl,monthKey:mk,summary};'
W '}'
W 'function exNums(text){'
W '  const ln=text.split(/\r?\n/);let s=-1;'
W '  for(let i=ln.length-1;i>=0;i--){if(/SALDO\s+AWAL\s*:/i.test(ln[i])){s=i;break}}'
W '  if(s<0)return null;'
W '  const b=ln.slice(s,Math.min(s+12,ln.length)).join(" ");'
W '  const v=[...b.matchAll(/\d{1,3}(?:[,.]\d{3})*(?:[,.]\d{2})|\d+(?:[,.]\d{2})/g)].map(m=>m[0]);'
W '  if(v.length<4)return null;'
W '  return{op:v[0],cr:v[1],db:v[2],en:v[3]};'
W '}'
W 'function finTx(cur,meta){'
W '  const body=cur.lines.join(" ").replace(/\s+/g," ").trim();'
W '  if(!body||/SALDO\s+AWAL/i.test(body))return null;'
W '  const isDB=/\bDB\b/i.test(body);'
W '  const aR=/(\d{1,3}(?:[,.]\d{3})*(?:[,.]\d{2})|\d+(?:[,.]\d{2}))(?:\s*DB)?/g;'
W '  const ams=[...body.matchAll(aR)];if(!ams.length)return null;'
W '  let am=ams[0];if(isDB)am=ams.find(m=>/\bDB\b/i.test(body.slice(m.index,m.index+m[0].length+4)))||am;'
W '  else if(ams.length>1)am=/TRSF|BI-FAST|SETORAN|CDM/i.test(body)?ams[0]:(ams[1]||ams[0]);'
W '  const amount=pM(am[1]);const type=isDB?"out":"in";'
W '  const dk=`${cur.year}-${String(cur.month+1).padStart(2,"0")}-${String(cur.day).padStart(2,"0")}`;'
W '  const dd=`${String(cur.day).padStart(2,"0")}/${String(cur.month+1).padStart(2,"0")}/${cur.year}`;'
W '  const cd=body.replace(aR," ").replace(/\bCBG\b|\bMUTASI\b|\bSALDO\b/gi," ").replace(/\s+/g," ").trim();'
W '  const party=exPty(cd||body);const cat=catTx(cd||body,type,party);'
W '  return{id:`BCA-${dk}-${Math.round(amount)}`,source:"BCA",date:dk,displayDate:dd,monthKey:`${cur.year}-${String(cur.month+1).padStart(2,"0")}`,year:cur.year,type,amount,party,category:cat,description:cd||body,riskFlagged:(cat==="QRIS"&&isRisk(party)),iconColor:"#0060af",iconLabel:"BCA"};'
W '}'
W 'function exPty(d){'
W '  const t=d.replace(/\s+/g," ").trim();'
W '  const q=t.match(/QR\s*\d+\s+0+\.00\s*([A-Z0-9][A-Z0-9 ._-]{2,40})/i);if(q)return cPty(q[1]);'
W '  const ke=t.match(/TRANSFER\s+KE\s+\d+\s+([A-Z][A-Z\s.''-]{3,40})/i);if(ke)return cPty(ke[1]);'
W '  const dr=t.match(/TRANSFER\s+DR\s+\d+\s+([A-Z][A-Z\s.''-]{3,40})/i);if(dr)return cPty(dr[1]);'
W '  const w=t.match(/\b(GO-PAY CUSTO|GOPAY|DANA|SHOPEEPAY|SHOPEE|OVO|LINKAJA)\b/i);if(w)return cPty(w[0]);'
W '  const m=t.match(/\b(ALFAMRT|ALFAMART|INDOMARET|EDC Mini-AT|DOMPET ANAK BANGSA)[A-Z0-9\s.-]*/i);if(m)return cPty(m[0]);'
W '  const ws=t.split(" ").filter(p=>/[A-Z]/i.test(p)&&!/^\d/.test(p));'
W '  return ws.length>=2?cPty(ws.slice(-4).join(" ")):"BCA Mutation";'
W '}'
W 'function cPty(v){return String(v||"").replace(/^\/+/,"").replace(/\bTGL:.*$/i,"").replace(/\bDB\b/gi,"").replace(/\s+/g," ").trim()||"BCA Party"}'
W 'function catTx(d,type,party){'
W '  const t=(d+" "+party).toLowerCase();'
W '  if(t.includes("qr ")||t.includes("qris"))return"QRIS";'
W '  if(t.includes("tarikan atm")||t.includes("tarik tunai"))return"ATM";'
W '  if(t.includes("biaya adm"))return"Admin";'
W '  if(t.includes("dana")||t.includes("gopay")||t.includes("go-pay")||t.includes("shopee")||t.includes("ovo")||t.includes("linkaja"))return"E-Wallet";'
W '  if(t.includes("trsf")||t.includes("transfer")||t.includes("bi-fast"))return type==="in"?"Transfer Masuk":"Transfer Keluar";'
W '  if(t.includes("alfamart")||t.includes("indomaret"))return"Belanja";'
W '  return type==="in"?"Masuk Lain":"Keluar Lain";'
W '}'
W 'function isRisk(p){const t=p.toLowerCase();return["obsian","soulshard","slot","bet","game","craft","topup"].some(w=>t.includes(w))}'

